    return np.array(sel)
def kmeans_anchors(Zt, m, it=15, seed=0):
    rng=np.random.RandomState(seed); Cc=Zt[rng.choice(len(Zt),m,replace=False)].copy()
    for _ in range(it):
        a=np.argmax(Zt@Cc.T,1)
